import {useState, useMemo, useEffect} from 'react'
import {VisuallyHidden} from '@primer/react'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {ChartCard} from '@github-ui/chart-card'

import {ErrorComponent, LoadingComponent, NoDataComponent} from '../..'
import {AIUsageViewMode, RequestState, UsagePeriod} from '../../../enums'
import {getPeriodText, parseMoneyString} from '../../../utils'
import styles from '../UsageChart.module.css'

import type {Filters, UsageChartData} from '../../../types/usage'

// Construct once at module scope rather than per-render (the chart can re-render
// many times per session and `Intl.NumberFormat` construction is expensive).
const currencyFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
})

interface AIUsageChartProps {
  filters: Filters
  requestState: RequestState
  usage: UsageChartData[]
  viewMode: AIUsageViewMode
}

interface AggregatedBar {
  name: string
  included: number
  overage: number
  custom: {
    grossAmount: string
    discountAmount: string
    totalAmount: string
  }
}

const isLoadingStates = new Set<RequestState>([RequestState.INIT, RequestState.LOADING])

function formatMoney(value: number) {
  return `$${value.toFixed(2)}`
}

function money2Number(value?: string | number) {
  return typeof value === 'number' ? value : parseMoneyString(value ?? '0')
}
/**
 * Compute a "nice" tick interval for the y-axis based on the max data value.
 * Picks round increments (1, 2, 5, 10, 25, 50, 100, ...) that produce ~4-5 ticks.
 */
export function getNiceTickInterval(maxValue: number) {
  if (maxValue <= 0) return 1

  const roughStep = maxValue / 5
  const magnitude = Math.pow(10, Math.floor(Math.log10(roughStep)))
  const normalized = roughStep / magnitude

  let niceStep: number
  if (normalized <= 1) niceStep = 1
  else if (normalized <= 2) niceStep = 2
  else if (normalized <= 5) niceStep = 5
  else niceStep = 10

  return Math.max(1, niceStep * magnitude)
}

function formatDateLabel(timestamp: number, isYearly = false) {
  const date = new Date(timestamp)
  if (isYearly) {
    return date.toLocaleDateString('en-US', {month: 'short', timeZone: 'UTC'})
  }
  return date.toLocaleDateString('en-US', {month: 'short', day: 'numeric', timeZone: 'UTC'})
}

function aggregateByModel(usage: UsageChartData[]): AggregatedBar[] {
  const allModels = usage
    .map(dataset => {
      const name = (dataset as UsageChartData & {name?: string}).name ?? 'Unknown'
      let totalGross = 0
      let totalDiscount = 0
      for (const point of dataset.data) {
        const gross = money2Number(point.custom.grossAmount)
        const discount = money2Number(point.custom.discountAmount)

        totalGross += gross
        totalDiscount += discount
      }

      const totalOverage = Math.max(totalGross - totalDiscount, 0)
      return {
        name,
        included: Math.round(totalDiscount * 100) / 100,
        overage: Math.round(totalOverage * 100) / 100,
        custom: {
          grossAmount: formatMoney(totalGross),
          discountAmount: formatMoney(totalDiscount),
          totalAmount: formatMoney(totalOverage),
        },
      }
    })
    .filter(model => model.included > 0 || model.overage > 0)
    .sort((a, b) => b.included + b.overage - (a.included + a.overage))

  if (allModels.length <= 5) return allModels

  const topModels = allModels.slice(0, 5)
  const otherModels = allModels.slice(5)
  const otherIncluded = otherModels.reduce((sum, m) => sum + m.included, 0)
  const otherOverage = otherModels.reduce((sum, m) => sum + m.overage, 0)

  topModels.push({
    name: 'Other models',
    included: Math.round(otherIncluded * 100) / 100,
    overage: Math.round(otherOverage * 100) / 100,
    custom: {
      grossAmount: formatMoney(otherIncluded + otherOverage),
      discountAmount: formatMoney(otherIncluded),
      totalAmount: formatMoney(otherOverage),
    },
  })

  return topModels
}

function aggregateByDay(usage: UsageChartData[], isYearly = false): AggregatedBar[] {
  const dayMap = new Map<number, {gross: number; discount: number}>()
  const now = Date.now()

  for (const dataset of usage) {
    for (const point of dataset.data) {
      if (point.x > now) continue
      const gross = money2Number(point.custom.grossAmount)
      const discount = money2Number(point.custom.discountAmount)
      const existing = dayMap.get(point.x) ?? {gross: 0, discount: 0}
      existing.gross += gross
      existing.discount += discount
      dayMap.set(point.x, existing)
    }
  }

  return Array.from(dayMap.entries())
    .sort(([a], [b]) => a - b)
    .map(([timestamp, {gross, discount}]) => {
      const overage = Math.max(gross - discount, 0)
      return {
        name: formatDateLabel(timestamp, isYearly),
        included: Math.round(discount * 100) / 100,
        overage: Math.round(overage * 100) / 100,
        custom: {
          grossAmount: formatMoney(gross),
          discountAmount: formatMoney(discount),
          totalAmount: formatMoney(overage),
        },
      }
    })
}

function getChartTitle(viewMode: AIUsageViewMode, isYearly: boolean): string {
  if (viewMode === AIUsageViewMode.MODELS) {
    return 'Model usage'
  }
  return isYearly ? 'Monthly usage' : 'Daily usage'
}

const UTC_SHORT_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

function getSubtitleText(period: Filters['period']): string {
  if (period?.type === UsagePeriod.THIS_MONTH) {
    const now = new Date()
    const month = UTC_SHORT_MONTHS[now.getUTCMonth()]
    const day = now.getUTCDate()
    const year = now.getUTCFullYear()
    return `${month} 1 - ${month} ${day}, ${year}`
  }
  return getPeriodText(period)
}

export default function AIUsageUserChart(props: AIUsageChartProps) {
  const {filters, requestState, usage, viewMode} = props
  const [screenReaderAnnouncement, setScreenReaderAnnouncement] = useState('')

  const periodType = filters?.period?.type
  const isYearlyPeriod = periodType === UsagePeriod.THIS_YEAR || periodType === UsagePeriod.LAST_YEAR

  const bars = useMemo(
    () => (viewMode === AIUsageViewMode.MODELS ? aggregateByModel(usage) : aggregateByDay(usage, isYearlyPeriod)),
    [usage, viewMode, isYearlyPeriod],
  )

  const hasData = bars.some(b => b.included > 0 || b.overage > 0)
  const title = getChartTitle(viewMode, isYearlyPeriod)
  const subtitle = getSubtitleText(filters.period)

  useEffect(() => {
    if (isLoadingStates.has(requestState)) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setScreenReaderAnnouncement('Loading usage data...')
    } else if (requestState === RequestState.ERROR) {
      setScreenReaderAnnouncement('Error loading usage data.')
    } else if (requestState === RequestState.IDLE) {
      if (!hasData) {
        setScreenReaderAnnouncement('No usage data found for the selected filters.')
      } else {
        setScreenReaderAnnouncement(
          `${title} chart showing data for ${subtitle}. ${bars.length} ${bars.length === 1 ? 'item' : 'items'}.`,
        )
      }
    }
  }, [requestState, hasData, title, subtitle, bars.length])

  const maxValue = useMemo(() => bars.reduce((max, b) => Math.max(max, b.included + b.overage), 0), [bars])
  const tickInterval = useMemo(() => getNiceTickInterval(maxValue), [maxValue])
  const yAxisMax = useMemo(() => Math.ceil(maxValue / tickInterval) * tickInterval, [maxValue, tickInterval])

  return (
    <div data-hpc>
      <VisuallyHidden role="status">{screenReaderAnnouncement}</VisuallyHidden>
      <ErrorBoundary
        fallback={
          <div className="tmp-mb-3">
            <ChartCard size="xl" border>
              <ChartCard.Title>{title}</ChartCard.Title>
              <ChartCard.Description>{subtitle}</ChartCard.Description>
              <ErrorComponent
                className={styles.innerContainer}
                testid="ai-usage-chart-error-boundary"
                text="Unable to load chart"
              />
            </ChartCard>
          </div>
        }
        appName="billing-app"
      >
        <div className="tmp-mb-3">
          {isLoadingStates.has(requestState) && (
            <div className={styles.container}>
              <div className={styles.chartHeaderContainer}>
                <div>
                  <h3 className={styles.chartTitle}>{title}</h3>
                  <span className={styles.chartSubtitle}>{subtitle}</span>
                </div>
              </div>
              <LoadingComponent className={styles.innerContainerStyle} testid="ai-usage-loading-spinner" />
            </div>
          )}
          {requestState === RequestState.ERROR && (
            <div className={styles.container}>
              <ErrorComponent
                className={styles.innerContainer}
                testid="ai-usage-loading-error"
                text="Something went wrong"
              />
            </div>
          )}
          {requestState === RequestState.IDLE && !hasData && (
            <div className={styles.container}>
              <NoDataComponent className={styles.innerContainer} testid="ai-usage-no-data" text="No usage" />
            </div>
          )}
          {requestState === RequestState.IDLE && hasData && (
            <ChartCard size="xl" border visibleChartOptions={false}>
              <ChartCard.Title as="h3" className={styles.chartTitle}>
                {title}
              </ChartCard.Title>
              <ChartCard.Description>{subtitle}</ChartCard.Description>
              <ChartCard.Chart
                series={[
                  {
                    name: 'Included usage',
                    data: bars.map(b => ({name: b.name, y: b.included, custom: b.custom})),
                    type: 'column',
                    color: 'var(--display-blue-scale-4)',
                  },
                  {
                    name: 'Overage',
                    data: bars.map(b => ({name: b.name, y: b.overage, custom: b.custom})),
                    type: 'column',
                  },
                ]}
                xAxisTitle="Category"
                yAxisTitle="Spend"
                xAxisOptions={{
                  type: 'category',
                  title: {text: null},
                  gridLineWidth: 0,
                }}
                yAxisOptions={{
                  labels: {
                    formatter() {
                      return this.value === 0 ? '0' : `${currencyFormatter.format(this.value as number)}`
                    },
                  },
                  title: {text: null},
                  tickInterval,
                  max: yAxisMax,
                  gridLineDashStyle: 'Dot',
                  endOnTick: true,
                }}
                type="column"
                overrideOptionsNotRecommended={{
                  chart: {spacingLeft: 5},
                  legend: {enabled: true},
                  tooltip: {
                    useHTML: true,
                    shared: true,
                    formatter() {
                      const points = this.points ?? []
                      const label = points[0]?.point?.name ?? ''
                      const lines = points.map(p => {
                        const custom = (
                          p.point as unknown as {custom?: {discountAmount?: string; totalAmount?: string}}
                        ).custom
                        const amount =
                          p.series.name === 'Included usage'
                            ? (custom?.discountAmount ?? '$0.00')
                            : (custom?.totalAmount ?? '$0.00')
                        // eslint-disable-next-line github/unescaped-html-literal
                        return `<div><span style="color:${p.series.color}">\u25CF</span> ${p.series.name}: <strong>${amount}</strong></div>`
                      })
                      // eslint-disable-next-line github/unescaped-html-literal
                      return `<div style="font-size:12px;margin-bottom:8px">${label}</div>${lines.join('')}`
                    },
                  },
                  plotOptions: {
                    column: {
                      stacking: 'normal',
                      colorByPoint: false,
                      borderRadius: 0,
                    },
                  },
                  accessibility: {
                    keyboardNavigation: {order: ['series']},
                    point: {
                      descriptionFormatter(point: Highcharts.Point) {
                        const custom = (
                          point as unknown as {
                            custom?: {discountAmount?: string; totalAmount?: string; grossAmount?: string}
                          }
                        ).custom

                        const seriesAmounts: Record<string, string | undefined> = {
                          'Included usage': custom?.discountAmount,
                          Overage: custom?.totalAmount,
                        }
                        const amount = seriesAmounts[point.series.name] ?? custom?.grossAmount ?? '$0.00'

                        return `${point.name}: ${amount}`
                      },
                    },
                  },
                }}
              />
            </ChartCard>
          )}
        </div>
      </ErrorBoundary>
    </div>
  )
}
